Here's how to handle each scenario with MSTest 3.9+/3.10+ attributes:

```csharp
[TestClass]
public sealed class MyTests : IDisposable
{
    private string? _tempFile;

    // 1. Windows-only (registry access)
    [TestMethod]
    [OSCondition(OperatingSystems.Windows)]
    public void Registry_ReadsExpectedValue()
    {
        var value = Registry.GetValue(@"HKEY_LOCAL_MACHINE\SOFTWARE\MyApp", "Setting", null);
        Assert.IsNotNull(value);
    }

    // 2. Skip in CI (requires local GPU)
    [TestMethod]
    [CICondition(ConditionMode.Exclude)]
    public void RenderFrame_UsesGpuAcceleration()
    {
        var result = GpuRenderer.RenderTestFrame();
        Assert.IsTrue(result.UsedHardwareAcceleration);
    }

    // 3. Flaky external API — retry up to 3 times
    [TestMethod]
    [Retry(3)]
    public async Task WeatherApi_ReturnsForecast()
    {
        var forecast = await WeatherClient.GetForecastAsync("Seattle");
        Assert.IsNotNull(forecast);
    }

    // 4. Cleanup temp files even on failure
    [TestMethod]
    public void Export_WritesToTempFile()
    {
        _tempFile = Path.GetTempFileName();
        FileExporter.Export(_tempFile);
        Assert.IsNotEmpty(File.ReadAllText(_tempFile));
    }

    [TestCleanup]
    public void Cleanup()
    {
        if (_tempFile is not null && File.Exists(_tempFile))
            File.Delete(_tempFile);
    }

    public void Dispose() => Cleanup(); // belt-and-suspenders
}
```

**Key points:**

| Scenario | Solution |
|----------|----------|
| Windows-only | `[OSCondition(OperatingSystems.Windows)]` — skips on other OSes |
| Skip in CI | `[CICondition(ConditionMode.Exclude)]` — skips when CI env detected |
| Flaky API | `[Retry(3)]` — retries up to 3 times (MSTest 3.9+) |
| Temp file cleanup | `[TestCleanup]` — runs after every test, even on failure |

`[TestCleanup]` is guaranteed to run regardless of test outcome, making it ideal for resource cleanup. For async cleanup, use `Task`-returning `[TestCleanup]` methods.
